func boom(n int) {
    if n == 0 {
        fmt.Println("пуск")
        return
    }
    fmt.Println(n)
    boom(n - 1)
}

func main() {
    boom(3)
}

package main

import "fmt"

func echo(n int) {
    if n == 0 {
        return
    }
    echo(n - 1)
    fmt.Println(n)
}

func main() {
    echo(3)
}

